-- name: ListCopilotEvents :many
SELECT * FROM copilot_events ORDER BY session_id;

-- name: InsertCopilotEvents :exec
INSERT INTO copilot_events (session_id, event_key, source_key, source, observed_session_id, trace_id, span_id, event_id, start_time, state, metric_series, time, event_type, content, role, tool, call_id, args, result, error, warning, agent, parent, model, metadata, raw, temporality) VALUES (sqlc.arg(session_id), sqlc.arg(event_key), sqlc.arg(source_key), sqlc.arg(source), sqlc.arg(observed_session_id), sqlc.arg(trace_id), sqlc.arg(span_id), sqlc.arg(event_id), sqlc.arg(start_time), sqlc.arg(state), sqlc.arg(metric_series), sqlc.arg(time), sqlc.arg(event_type), sqlc.arg(content), sqlc.arg(role), sqlc.arg(tool), sqlc.arg(call_id), sqlc.arg(args), sqlc.arg(result), sqlc.arg(error), sqlc.arg(warning), sqlc.arg(agent), sqlc.arg(parent), sqlc.arg(model), sqlc.arg(metadata), sqlc.arg(raw), sqlc.arg(temporality)) ON CONFLICT (session_id, event_key) DO UPDATE SET source_key = excluded.source_key, source = excluded.source, observed_session_id = excluded.observed_session_id, trace_id = excluded.trace_id, span_id = excluded.span_id, event_id = excluded.event_id, start_time = excluded.start_time, state = excluded.state, metric_series = excluded.metric_series, time = excluded.time, event_type = excluded.event_type, content = excluded.content, role = excluded.role, tool = excluded.tool, call_id = excluded.call_id, args = excluded.args, result = excluded.result, error = excluded.error, warning = excluded.warning, agent = excluded.agent, parent = excluded.parent, model = excluded.model, metadata = excluded.metadata, raw = excluded.raw, temporality = excluded.temporality;

-- name: ClearCopilotEvents :exec
DELETE FROM copilot_events;
